-- TeknoVersus — 157 ürünün TAMAMI: genişletilmiş özellik alanlarıyla günceller
-- (Renk, Ağırlık, Konektör, Güvenlik, Kamera Sayısı vb. 13+ yeni alan, kategoriye göre uyarlanmış)
-- Supabase SQL Editor'de çalıştır. Büyük bir dosya, çalışması birkaç saniye sürebilir.

on conflict (id) do update set name=excluded.name, cat=excluded.cat, blurb=excluded.blurb, added_at=excluded.added_at, link=excluded.link, upcoming=excluded.upcoming, specs=excluded.specs, deleted=false;
